package com.ligamunicipal.api.model; import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*;
@Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames={"miembro_id","partido_id"})) public class AlineacionFantasy extends BaseEntity { @ManyToOne(optional=false) public MiembroEquipo miembro; @ManyToOne(optional=false) public PartidoJornada partido; public String formacion; public BigDecimal presupuestoGastado=BigDecimal.ZERO; public BigDecimal puntosJornada=BigDecimal.ZERO; public Instant fechaGuardado=Instant.now(); @OneToMany(mappedBy="alineacion",cascade=CascadeType.ALL) public List<DetalleAlineacion> detalles=new ArrayList<>(); }
